CREATE TABLE IF NOT EXISTS risktionary_user (id uuid PRIMARY KEY, email VARCHAR(256) NOT NULL, first_name VARCHAR(64) NOT NULL, last_name VARCHAR(64) NOT NULL, display_name VARCHAR(136) NOT NULL);
ALTER TABLE risktionary_user ADD CONSTRAINT risktionary_user_email_unique UNIQUE (email);
CREATE TABLE IF NOT EXISTS risktionary_oauth_account (user_id uuid, provider VARCHAR(32), provider_user_id VARCHAR(128) NOT NULL, email VARCHAR(256) NOT NULL, CONSTRAINT pk_risktionary_oauth_account PRIMARY KEY (user_id, provider), CONSTRAINT fk_risktionary_oauth_account_user_id__id FOREIGN KEY (user_id) REFERENCES risktionary_user(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE risktionary_oauth_account ADD CONSTRAINT risktionary_oauth_account_provider_provider_user_id_unique UNIQUE (provider, provider_user_id);